#[test]
fn test_find_count_flag() {
    let dir = setup_workspace();

    write(
        dir.path().join("doc1.md"),
        indoc! {"
            # Document One

            Content one.
        "},
    )
    .unwrap();

    write(
        dir.path().join("doc2.md"),
        indoc! {"
            # Document Two

            Content two.
        "},
    )
    .unwrap();

    write(
        dir.path().join("doc3.md"),
        indoc! {"
            # Document Three

            Content three.
        "},
    )
    .unwrap();

    let (stdout, _, success) = run_iwe(dir.path(), &["--count"]);
    assert!(success);
    assert_eq!(stdout.trim(), "3");

    // --count with query filter
    let (stdout, _, success) = run_iwe(dir.path(), &["--count", "One"]);
    assert!(success);
    assert_eq!(stdout.trim(), "1");

    // --count with --roots
    let (stdout, _, success) = run_iwe(dir.path(), &["--count", "--roots"]);
    assert!(success);
    assert_eq!(stdout.trim(), "3");
}
